use genewars_runtime::{creature_world::*,actor_activation::TrigTables,physics_tables::PhysicsTables};
use std::{fs,path::PathBuf};
fn main(){let p=PathBuf::from(std::env::args().nth(1).unwrap());let physics=PhysicsTables::from_mapped_bytes(&fs::read(p.join("angles.bin")).unwrap(),&fs::read(p.join("bounce.bin")).unwrap()).unwrap();let trig=TrigTables::generate_pinned().unwrap();let animations=MuleAnimations::from_anb(&fs::read(p.join("mule.anb")).unwrap()).unwrap();let input=fs::read(p.join("input.bin")).unwrap();let map=fs::read(p.join("map.bin")).unwrap();let mut actual=Vec::new();let mut checks=0;
 for row in input.chunks_exact(128){let frame=u32::from_le_bytes(row[..4].try_into().unwrap());let before:[u8;124]=row[4..].try_into().unwrap();let prefix=plan_common_straight_motion_prefix(&before,frame,&physics,&trig,true,true,true).unwrap();let target=[i16::from_le_bytes(prefix[11..13].try_into().unwrap()),i16::from_le_bytes(prefix[13..15].try_into().unwrap())];let mut contact_calls=0;
  let (got,effect)=plan_mule_after_admitted_prefix_with_water_policy(&before,&prefix,target,&map,MuleStepContext{frame_counter:frame,gravity:1024,water_height:1632,climate:106},&physics,&trig,|_,_,_|{contact_calls+=1;Ok(0)},|_|Ok(false),&animations,|_|Err(CreatureError::UnsupportedMotionState),true).unwrap_or_else(|e|panic!("frame{frame}:{e:?}"));
  actual.extend_from_slice(&got.after);assert_eq!(&got.after[..6],&before[..6]);assert_eq!(&got.after[31..39],&before[31..39]);assert!(effect.is_none());checks+=3;
  if before[94]>=24{assert_eq!(contact_calls,0);checks+=1;}
 }fs::write(p.join("actual.bin"),actual).unwrap();println!("{} mortality afterimages; {checks} checks",input.len()/128);}
